static float hashf(float x,float z){float v=sinf(x*12.9898f+z*78.233f)*43758.5453f;return v-floorf(v);} 
static float groundH(float x,float z){float h=sinf(x*.085f)*1.1f+cosf(z*.072f)*.9f+sinf((x+z)*.19f)*.35f+(hashf(floorf(x*.35f),floorf(z*.35f))-.5f)*.12f;return h*.42f;}
