static void resizeSwap(int w,int h){if(!g_swap||w<1||h<1)return;g_w=w;g_h=h;destroySize();if(SUCCEEDED(g_swap->ResizeBuffers(0,g_w,g_h,DXGI_FORMAT_UNKNOWN,0)))createSize();}
